#!/bin/sh
# Regenerates reset_database.sql = wipe everything + schema migration + seed.
cd "$(dirname "$0")"
{
cat <<'HDR'
-- ⚠ DESTRUCTIVE: wipes the ENTIRE public schema and ALL auth users, then rebuilds from scratch
-- (schema, RLS, RPCs, realtime) and seeds the admin + a customer + 1 lot + 2 hardware slots.
-- Paste the whole file into the Supabase SQL Editor and run it once. Take a backup first.
-- Generated by supabase/build-reset.sh from migrations/*_schema.sql + seed.sql - do not edit by hand.

-- Drop the app schema first: the old bookings table blocks deleting users (ON DELETE RESTRICT).
DROP SCHEMA IF EXISTS public CASCADE;
DELETE FROM auth.users;           -- cascades identities, sessions and refresh tokens
CREATE SCHEMA public;
GRANT USAGE ON SCHEMA public TO postgres, anon, authenticated, service_role;
GRANT ALL ON SCHEMA public TO postgres, service_role;

HDR
cat migrations/*_schema.sql
echo
cat seed.sql
echo
echo "-- Make the API pick up the new tables and functions immediately."
echo "NOTIFY pgrst, 'reload schema';"
} > reset_database.sql
